import{_ as r,o,c as i,a2 as l}from"./chunks/framework.DDEX3mHW.js";const c=JSON.parse('{"title":"流量转发与管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/forward.md","filePath":"guide/forward.md","lastUpdated":1792059802000}'),e={name:"guide/forward.md"};function t(n,a,s,d,h,u){return o(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="流量转发与管理" tabindex="-1">流量转发与管理 <a class="header-anchor" href="#流量转发与管理" aria-label="Permalink to &quot;流量转发与管理&quot;">​</a></h1><p>面板保留了原有的转发面板功能：多用户、端口转发和隧道转发、配额与限速。</p><h2 id="仪表盘-dashboard" tabindex="-1">仪表盘 (Dashboard) <a class="header-anchor" href="#仪表盘-dashboard" aria-label="Permalink to &quot;仪表盘 (Dashboard)&quot;">​</a></h2><p>登录系统后首先看到的是仪表盘，这里展示了系统的整体运行状态，包括：</p><ul><li>在线节点数量</li><li>用户总数</li><li>流量统计信息</li></ul><h2 id="节点管理-node" tabindex="-1">节点管理 (Node) <a class="header-anchor" href="#节点管理-node" aria-label="Permalink to &quot;节点管理 (Node)&quot;">​</a></h2><p>节点是实际承载流量转发的服务器。</p><ul><li><strong>添加节点</strong>: 点击“添加”，获取密钥用于节点端安装。</li><li><strong>管理</strong>: 可以查看节点在线状态、版本信息，以及对节点进行编辑或删除。</li></ul><h2 id="用户管理-user" tabindex="-1">用户管理 (User) <a class="header-anchor" href="#用户管理-user" aria-label="Permalink to &quot;用户管理 (User)&quot;">​</a></h2><p>管理员可以创建和管理普通用户。</p><ul><li><strong>创建用户</strong>: 设置用户名、密码、流量配额等。</li><li><strong>用户组</strong>: 可以将用户分配到不同的组 (Group)，便于统一管理权限或策略。</li></ul><h2 id="转发管理-forward" tabindex="-1">转发管理 (Forward) <a class="header-anchor" href="#转发管理-forward" aria-label="Permalink to &quot;转发管理 (Forward)&quot;">​</a></h2><p>这是核心功能区，用于设置端口转发规则。</p><ul><li><strong>端口转发</strong>: 将节点服务器的某个端口流量转发到目标地址。 <ul><li><strong>协议</strong>: 支持 TCP / UDP。</li><li><strong>入口</strong>: 选择入口节点和监听端口。</li><li><strong>出口</strong>: 设置目标 IP 和端口。</li></ul></li><li><strong>隧道转发</strong>: 用于更复杂的网络穿透场景（具体配置视业务需求而定）。</li></ul><h2 id="限制与策略-limit" tabindex="-1">限制与策略 (Limit) <a class="header-anchor" href="#限制与策略-limit" aria-label="Permalink to &quot;限制与策略 (Limit)&quot;">​</a></h2><ul><li><strong>限速</strong>: 可以对指定用户或指定隧道进行带宽限制，防止资源滥用。</li><li><strong>计费模式</strong>: 支持配置流量计算方式（单向或双向），适合运营场景。</li></ul><h2 id="系统配置-config" tabindex="-1">系统配置 (Config) <a class="header-anchor" href="#系统配置-config" aria-label="Permalink to &quot;系统配置 (Config)&quot;">​</a></h2><p>在此页面进行系统的全局设置。</p><h2 id="个人设置-profile" tabindex="-1">个人设置 (Profile) <a class="header-anchor" href="#个人设置-profile" aria-label="Permalink to &quot;个人设置 (Profile)&quot;">​</a></h2><ul><li><strong>修改密码</strong>: 为了安全，建议定期修改管理员密码。</li></ul>',20)])])}const f=r(e,[["render",t]]);export{c as __pageData,f as default};
